0\u0437\u043e\u0432\u044b\u0445 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u00bb\n**\u0426\u0435\u043b\u044c**: \u043f\u0440\u0435\u0432\u0440\u0430\u0442\u0438\u0442\u044c \u043d\u0430\u0431\u043e\u0440 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440 (\u043a\u043e\u043b\u043e\u043d\u043a\u0430 SMILES \u043b\u0438\u0431\u043e SDF) \u0432 \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u0443\u044e \u0442\u0430\u0431\u043b\u0438\u0446\u0443 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0438\u0440\u0443\u0435\u043c\u044b\u0445 2D-\u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432 \u0438 \u0434\u0430\u0442\u044c \u043e\u0442\u0447\u0451\u0442 \u043e \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435 \u0434\u0430\u043d\u043d\u044b\u0445. \u042d\u0442\u043e \u00ab\u0431\u0430\u0437\u0430\u00bb, \u043f\u043e\u0442\u043e\u043c\u0443 \u0447\u0442\u043e: (\u0430) \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430 \u0443\u043d\u0438\u0432\u0435\u0440\u0441\u0430\u043b\u044c\u043d\u044b \u0438 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0438\u0440\u0443\u0435\u043c\u044b, \u043d\u0435 \u0437\u0430\u0432\u0438\u0441\u044f\u0442 \u043e\u0442 \u0437\u0430\u0434\u0430\u0447 QSAR/\u0441\u043a\u0440\u0438\u043d\u0438\u043d\u0433\u0430; (\u0431) \u0434\u0430\u044e\u0442 \u043f\u0435\u0440\u0432\u044b\u0435 \u0444\u0438\u043b\u044c\u0442\u0440\u044b (\u043f\u0440\u0430\u0432\u0438\u043b\u043e \u041b\u0438\u043f\u0438\u043d\u0441\u043a\u0438), \u0434\u0435\u0434\u0443\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u044e \u0438 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044e; (\u0432) \u0432\u0441\u0435 \u043e\u043d\u0438 \u0442\u043e\u043f\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u2014 \u043d\u0435 \u0442\u0440\u0435\u0431\u0443\u044e\u0442 \u043a\u043e\u043d\u0444\u043e\u0440\u043c\u0435\u0440\u043e\u0432/3D, \u0434\u0451\u0448\u0435\u0432\u044b \u0438 \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u044b.\n\n**\u0412\u044b\u0431\u0440\u0430\u043d\u043d\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0431\u0430\u0437\u043e\u0432\u044b\u0445 \u0441\u0432\u043e\u0439\u0441\u0442\u0432 (\u044f\u0432\u043d\u044b\u0439 \u0441\u043f\u0438\u0441\u043e\u043a):**\n1. \u041a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 SMILES, InChI, InChIKey, \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u044f\u0440\u043d\u0430\u044f \u0444\u043e\u0440\u043c\u0443\u043b\u0430.\n2. \u041c\u043e\u043b\u0435\u043a\u0443\u043b\u044f\u0440\u043d\u0430\u044f \u043c\u0430\u0441\u0441\u0430 (MW) \u0438 \u0442\u043e\u0447\u043d\u0430\u044f \u043c\u0430\u0441\u0441\u0430.\n3. \u0427\u0438\u0441\u043b\u043e \u0442\u044f\u0436\u0451\u043b\u044b\u0445 \u0430\u0442\u043e\u043c\u043e\u0432; \u043f\u043e\u043b\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0430\u0442\u043e\u043c\u043e\u0432; \u0441\u0447\u0451\u0442\u0447\u0438\u043a\u0438 \u043f\u043e \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u0430\u043c.\n4. \u0427\u0438\u0441\u043b\u043e \u0441\u0432\u044f\u0437\u0435\u0439 \u0432\u0441\u0435\u0433\u043e \u0438 \u043f\u043e \u043f\u043e\u0440\u044f\u0434\u043a\u0443 (\u043e\u0434\u0438\u043d\u0430\u0440\u043d\u044b\u0435/\u0434\u0432\u043e\u0439\u043d\u044b\u0435/\u0442\u0440\u043e\u0439\u043d\u044b\u0435/\u0430\u0440\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435).\n5. \u0427\u0438\u0441\u043b\u043e \u0432\u0440\u0430\u0449\u0430\u044e\u0449\u0438\u0445\u0441\u044f \u0441\u0432\u044f\u0437\u0435\u0439.\n6. HBD (\u0434\u043e\u043d\u043e\u0440\u044b H-\u0441\u0432\u044f\u0437\u0438), HBA (\u0430\u043a\u0446\u0435\u043f\u0442\u043e\u0440\u044b H-\u0441\u0432\u044f\u0437\u0438).\n7. \u0422\u043e\u043f\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0430\u044f PSA (TPSA).\n8. logP (\u0440\u0435\u0434\u0430\u043a\u0446\u0438\u044f Crippen).\n9. \u0427\u0438\u0441\u043b\u043e \u043a\u043e\u043b\u0435\u0446 (SSSR), \u0447\u0438\u0441\u043b\u043e \u0430\u0440\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043a\u043e\u043b\u0435\u0446.\n10. \u0414\u043e\u043b\u044f sp3-\u0443\u0433\u043b\u0435\u0440\u043e\u0434\u0430 (CSP3).\n11. \u0424\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0437\u0430\u0440\u044f\u0434 (\u0441\u0443\u043c\u043c\u0430\u0440\u043d\u044b\u0439).\n12. \u0427\u0438\u0441\u043b\u043e \u0445\u0438\u0440\u0430\u043b\u044c\u043d\u044b\u0445 \u0446\u0435\u043d\u0442\u0440\u043e\u0432.\n\n## 2. \u0414\u043e\u043f\u0443\u0441\u043a\u0430\u0435\u043c\u0430\u044f \u0441\u0445\u0435\u043c\u0430 \u0432\u0445\u043e\u0434\u0430 \u0438 \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0438\n- \u0412 workspace \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430 \u043d\u0435\u0442; \u0434\u0438\u0437\u0430\u0439\u043d \u0441\u0442\u0440\u043e\u0438\u0442\u0441\u044f \u043d\u0430 \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0441\u0445\u0435\u043c\u0435: (a) \u0442\u0430\u0431\u043b\u0438\u0446\u0430 CSV/TSV \u0441 \u043a\u043e\u043b\u043e\u043d\u043a\u043e\u0439-\u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u043e\u043c SMILES (\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u0443\u0436\u0435 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0449\u0430\u044f \u043f\u043e\u043b\u044f \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432) \u0438\u043b\u0438 (b) SDF (\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b + \u043f\u043e\u043b\u044f \u0434\u0430\u043d\u043d\u044b\u0445).\n- \u0420\u0430\u0437\u043c\u0435\u0440 \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u0435\u043d \u2192 \u043f\u043e\u0442\u043e\u043a\u043e\u0432\u044b\u0439/\u043f\u043e\u0444\u0430\u0439\u043b\u043e\u0432\u044b\u0439 \u0440\u0435\u0436\u0438\u043c \u0447\u0442\u0435\u043d\u0438\u044f (\u043f\u043e \u0441\u0442\u0440\u043e\u043a\u0430\u043c \u0434\u043b\u044f CSV, MolSupplier \u0434\u043b\u044f SDF), \u0431\u0435\u0437 \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0438 \u0432\u0441\u0435\u0433\u043e \u0444\u0430\u0439\u043b\u0430 \u0432 \u043f\u0430\u043c\u044f\u0442\u044c.\n- \u041f\u0443\u0441\u0442\u044b\u0435/\u043d\u0435\u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0435 SMILES \u043d\u0435 \u0443\u0434\u0430\u043b\u044f\u044e\u0442\u0441\u044f \u043c\u043e\u043b\u0447\u0430: \u043f\u043e\u043c\u0435\u0447\u0430\u044e\u0442\u0441\u044f \u043a\u0430\u043a missing, \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u0441\u044f \u0438\u0437 \u0440\u0430\u0441\u0447\u0451\u0442\u0430 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432, \u043d\u043e \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u0432 coverage (\u0440\u0430\u0437\u0434\u0435\u043b 5).\n\n## 3. \u0426\u0435\u043b\u0435\u0432\u043e\u0439 \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d (RDKit)\n\u0428\u0430\u0433\u0438:\n1. \u0417\u0430\u0433\u0440\u0443\u0437\u043a\u0430 \u0438 \u0438\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u044f \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043a\u043e\u0432; \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043a\u043e\u043b\u043e\u043d\u043a\u0438 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b.\n2. \u041f\u0430\u0440\u0441\u0438\u043d\u0433: `Chem.MolFromSmiles` / `Chem.MolFromMolBlock`.\n3. \u0414\u0435\u0441\u0430\u043b\u0442\u0438\u043d\u0433 (\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 7.1) \u0441 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435\u043c \u0438\u0441\u0445\u043e\u0434\u043d\u043e\u0433\u043e SMILES \u0432 \u0442\u0440\u0430\u0441\u0441\u0438\u0440\u043e\u0432\u043e\u0447\u043d\u043e\u0439 \u043a\u043e\u043b\u043e\u043d\u043a\u0435.\n4. \u041a\u0430\u043d\u043e\u043d\u0438\u0437\u0430\u0446\u0438\u044f; \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f InChI/InChIKey \u0438 \u0444\u043e\u0440\u043c\u0443\u043b\u044b.\n5. \u0420\u0430\u0441\u0447\u0451\u0442 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432 (\u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0435 \u00ab\u0444\u0443\u043d\u043a\u0446\u0438\u044f RDKit \u2014 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u043e\u00bb):\n   - MW \u2192 `Descriptors.MolWt`; \u0442\u043e\u0447\u043d\u0430\u044f \u043c\u0430\u0441\u0441\u0430 \u2192 `Descriptors.ExactMolWt`;\n   - \u0444\u043e\u0440\u043c\u0443\u043b\u0430 \u2192 `rdMolDescriptors.CalcMolFormula`;\n   - \u0442\u044f\u0436\u0451\u043b\u044b\u0435 \u0430\u0442\u043e\u043c\u044b \u2192 `Lipinski.HeavyAtomCount`; \u043f\u043e\u043b\u043d\u044b\u0435 \u0430\u0442\u043e\u043c\u044b \u2192 `Mol.GetNumAtoms`; counts \u043f\u043e \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u0430\u043c \u2192 `Counter(atom.GetSymbol())`;\n   - \u0441\u0432\u044f\u0437\u0438 \u2192 `Mol.GetNumBonds` + \u0440\u0430\u0437\u0431\u0438\u0432\u043a\u0430 \u043f\u043e `BondType`;\n   - \u0432\u0440\u0430\u0449\u0430\u044e\u0449\u0438\u0435\u0441\u044f \u2192 `Lipinski.NumRotatableBonds`; HBD/HBA \u2192 `Lipinski.NumHDonors/NumHAcceptors` (\u0438\u043b\u0438 `CalcNumHBD/HBA`);\n   - TPSA \u2192 `CalcTPSA`; logP \u2192 `Crippen.MolLogP` (\u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c Crippen);\n   - \u043a\u043e\u043b\u044c\u0446\u0430 \u2192 `CalcNumRings` + `GetRingInfo()` (SSSR); \u0430\u0440\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u2192 `CalcNumAromaticRings`;\n   - CSP3 \u2192 `CalcFractionCSP3`; \u0437\u0430\u0440\u044f\u0434 \u2192 `Chem.GetFormalCharge` (\u0441\u0443\u043c\u043c\u0430 \u043f\u043e \u0430\u0442\u043e\u043c\u0430\u043c); \u0445\u0438\u0440\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u2192 `CalcNumAtomStereoCenters`.\n6. \u042d\u043a\u0441\u043f\u043e\u0440\u0442: \u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u0441\u0432\u043e\u0439\u0441\u0442\u0432 (CSV/parquet) + \u0436\u0443\u0440\u043d\u0430\u043b \u043e\u0448\u0438\u0431\u043e\u043a.\n7. \u0412\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f (\u0440\u0430\u0437\u0434\u0435\u043b 4), \u0437\u0430\u0442\u0435\u043c \u0430\u043d\u0430\u043b\u0438\u0437 (\u0440\u0430\u0437\u0434\u0435\u043b 5).\n\n## 4. \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438 \u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u0438\n- **Parse-rate:** \u0434\u043e\u043b\u044f \u0443\u0441\u043f\u0435\u0448\u043d\u043e \u0440\u0430\u0441\u043f\u0430\u0440\u0441\u0435\u043d\u043d\u044b\u0445 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440 \u2265 99% (\u043f\u043e\u0440\u043e\u0433 \u0437\u0430\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0437\u0430\u0440\u0430\u043d\u0435\u0435); \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0439 \u043d\u0435\u0443\u0434\u0430\u0447\u0438 \u2014 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f \u043e\u0448\u0438\u0431\u043a\u0438 (\u0441\u0438\u043d\u0442\u0430\u043a\u0441\u0438\u0441 / \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0435 \u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u0438 / \u043f\u0443\u0441\u0442\u0430\u044f \u0441\u0442\u0440\u043e\u043a\u0430) \u0432 \u0436\u0443\u0440\u043d\u0430\u043b\u0435.\n- **Round-trip:** `SMILES \u2192 Mol \u2192 canonical SMILES \u2192 Mol` \u043e\u0431\u044f\u0437\u0430\u043d \u0434\u0430\u0442\u044c \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0449\u0438\u0435 \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0441\u0442\u0440\u043e\u043a\u0438; \u0438\u0437\u043e\u043c\u043e\u0440\u0444\u0438\u0437\u043c \u0433\u0440\u0430\u0444\u043e\u0432 \u0438\u0441\u0445\u043e\u0434\u043d\u043e\u0439 \u0438 \u00ab\u0432\u0442\u043e\u0440\u043e\u0439\u00bb \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u044b. \u0414\u043b\u044f SDF: `MolBlock \u2192 Mol \u2192 MolBlock \u2192 Mol` \u2014 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0430\u0442\u043e\u043c\u043d\u044b\u0445/\u0441\u0432\u044f\u0437\u043d\u044b\u0445 \u0441\u0447\u0451\u0442\u0447\u0438\u043a\u043e\u0432.\n- **\u0420\u0435\u043f\u0435\u0440\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 \u0441 \u0432\u0440\u0443\u0447\u043d\u0443\u044e \u043f\u043e\u0441\u0447\u0438\u0442\u0430\u043d\u043d\u044b\u043c\u0438 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\u043c\u0438** (\u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0435 \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u044b \u0434\u043b\u044f \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438, \u043d\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b): \u0432\u043e\u0434\u0430 H\u2082O (\u0444\u043e\u0440\u043c\u0443\u043b\u0430 H2O, MW\u224818.02, HBD=2, HBA=2, TPSA\u224820 \u043f\u043e \u0440\u0435\u0434\u0430\u043a\u0446\u0438\u0438), \u044d\u0442\u0430\u043d\u043e\u043b (C2H6O, MW\u224846.07, HBD=1), \u0431\u0435\u043d\u0437\u043e\u043b (C6H6, MW\u224878.11, 1 \u0430\u0440\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043a\u043e\u043b\u044c\u0446\u043e, TPSA=0, logP (Crippen)\u22481.8\u20132.0), \u0430\u0441\u043f\u0438\u0440\u0438\u043d (C9H8O4, MW\u2248180.16, 1 \u043a\u043e\u043b\u044c\u0446\u043e, HBD=1, HBA=4, TPSA\u224863.6). \u0414\u043e\u043f\u0443\u0441\u043a\u0438: \u0442\u043e\u0447\u043d\u044b\u0435 \u0441\u0447\u0451\u0442\u0447\u0438\u043a\u0438 \u2014 \u0440\u0430\u0432\u0435\u043d\u0441\u0442\u0432\u043e; MW \u00b10.02; TPSA \u00b10.1; logP \u00b10.2.\n- **\u0412\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0435 \u0438\u043d\u0432\u0430\u0440\u0438\u0430\u043d\u0442\u044b:** MW \u0441\u043e\u0433\u043b\u0430\u0441\u0443\u0435\u0442\u0441\u044f \u0441 \u0441\u0443\u043c\u043c\u043e\u0439 \u0430\u0442\u043e\u043c\u043d\u044b\u0445 \u043c\u0430\u0441\u0441 \u043f\u043e \u0444\u043e\u0440\u043c\u0443\u043b\u0435; \u0447\u0438\u0441\u043b\u043e \u0430\u0442\u043e\u043c\u043e\u0432 = \u0441\u0443\u043c\u043c\u0430 counts \u043f\u043e \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u0430\u043c; \u0447\u0438\u0441\u043b\u043e H \u0432 \u0444\u043e\u0440\u043c\u0443\u043b\u0435 = \u0441\u0443\u043c\u043c\u0435 H; 0 \u2264 HBD, HBA \u2264 \u0447\u0438\u0441\u043b\u043e \u0442\u044f\u0436\u0451\u043b\u044b\u0445 \u0430\u0442\u043e\u043c\u043e\u0432; TPSA \u2265 0; \u0447\u0438\u0441\u043b\u043e \u043a\u043e\u043b\u0435\u0446 \u2264 \u0447\u0438\u0441\u043b\u043e \u0430\u0442\u043e\u043c\u043e\u0432; \u0432\u0441\u0435 \u0441\u0447\u0451\u0442\u0447\u0438\u043a\u0438 \u043d\u0435\u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u044b; \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 NaN \u043f\u043e \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u0430\u043c.\n- **\u041a\u0440\u043e\u0441\u0441-\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0441 \u0443\u0436\u0435 \u0438\u043c\u0435\u044e\u0449\u0438\u043c\u0438\u0441\u044f \u043f\u043e\u043b\u044f\u043c\u0438** (\u0435\u0441\u043b\u0438 \u0434\u0430\u0442\u0430\u0441\u0435\u0442 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0441\u0432\u043e\u0438 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b): \u0434\u043e\u043f\u0443\u0441\u043a\u0438 \u043d\u0430 \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u044c, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 MW \u00b11% (\u0438\u043b\u0438 \u00b12 \u0430.\u0435.\u043c.), \u0441\u0447\u0451\u0442\u0447\u0438\u043a\u0438 \u0430\u0442\u043e\u043c\u043e\u0432/\u0441\u0432\u044f\u0437\u0435\u0439 \u00b11, logP \u00b10.5, TPSA \u2014 \u043f\u0440\u0438 \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u043c\u0435\u0442\u043e\u0434\u043e\u043b\u043e\u0433\u0438\u0438 \u00b12 \u00c5\u00b2. \u0420\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0441\u0432\u0435\u0440\u0445 \u0434\u043e\u043f\u0443\u0441\u043a\u0430 \u2192 \u0444\u043b\u0430\u0433 \u0432 \u043e\u0442\u0447\u0451\u0442\u0435.\n- **\u0414\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u044b/\u0441\u0442\u0435\u0440\u0435\u043e:** \u0434\u0435\u0434\u0443\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u044f \u043f\u043e InChIKey (\u0440\u0430\u0437\u043d\u044b\u0435 \u0441\u0442\u0435\u0440\u0435\u043e\u0438\u0437\u043e\u043c\u0435\u0440\u044b \u2014 \u0440\u0430\u0437\u043d\u044b\u0435 \u0437\u0430\u043f\u0438\u0441\u0438); \u0444\u043b\u0430\u0433 \u0434\u0443\u043f\u043b\u0438\u043a\u0430\u0442\u0430 \u0432\u043c\u0435\u0441\u0442\u043e \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u044f \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e.\n- **\u0412\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u044c:** \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c \u043e\u0434\u043d\u0443 \u0432\u0435\u0440\u0441\u0438\u044e RDKit (\u0446\u0435\u043b\u0435\u0432\u0430\u044f, \u043d\u0430\u043f\u0440. 2023.09.x), seed, \u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u043c \u0432\u0435\u0440\u0441\u0438\u0438 \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a \u0432 \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043e\u043a \u043e\u0442\u0447\u0451\u0442\u0430.\n\n## 5. \u041f\u043b\u0430\u043d \u0430\u043d\u0430\u043b\u0438\u0437\u0430\n- **\u041e\u043f\u0438\u0441\u0430\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430** \u043f\u043e \u043a\u0430\u0436\u0434\u043e\u043c\u0443 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0443: mean, median, std, min, max, \u043a\u0432\u0430\u043d\u0442\u0438\u043b\u0438 (1%, 5%, 25%, 75%, 95%, 99%).\n- **\u0420\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f:** \u0433\u0438\u0441\u0442\u043e\u0433\u0440\u0430\u043c\u043c\u044b + boxplot \u0434\u043b\u044f MW, logP, TPSA, \u0447\u0438\u0441\u043b\u0430 \u0442\u044f\u0436\u0451\u043b\u044b\u0445 \u0430\u0442\u043e\u043c\u043e\u0432, \u0447\u0438\u0441\u043b\u0430 \u043a\u043e\u043b\u0435\u0446.\n- **\u041a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u043e\u043d\u043d\u0430\u044f \u043c\u0430\u0442\u0440\u0438\u0446\u0430** \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432 (\u041f\u0438\u0440\u0441\u043e\u043d \u0438 \u0421\u043f\u0438\u0440\u043c\u0435\u043d) \u2014 \u0432\u044b\u044f\u0432\u043b\u0435\u043d\u0438\u0435 \u043a\u043e\u043b\u043b\u0438\u043d\u0435\u0430\u0440\u043d\u043e\u0441\u0442\u0438 (\u043e\u0436\u0438\u0434\u0430\u0435\u043c\u043e\u0435 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435, \u043d\u0430\u043f\u0440. MW\u2194\u0447\u0438\u0441\u043b\u043e \u0430\u0442\u043e\u043c\u043e\u0432, TPSA\u2194HBA, \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u043f\u043b\u0430\u043d \u043d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u044f, \u0430 \u043d\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442).\n- **\u0412\u044b\u0431\u0440\u043e\u0441\u044b:** IQR\u00d71.5 \u0438 |z|>3; \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u044f \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u043e\u0432 \u041b\u0438\u043f\u0438\u043d\u0441\u043a\u0438.\n- **\u041f\u0440\u0430\u0432\u0438\u043b\u043e \u041b\u0438\u043f\u0438\u043d\u0441\u043a\u0438:** \u0434\u043e\u043b\u0438 \u0441\u043e\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u0439 \u0441 MW\u2264500, logP\u22645, HBD\u22645, HBA\u226410; \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0447\u0438\u0441\u043b\u0430 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0439 \u043d\u0430 \u0441\u043e\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u0435.\n- **\u041f\u043e\u043a\u0440\u044b\u0442\u0438\u0435:** \u0434\u043e\u043b\u044f \u0441\u0442\u0440\u043e\u043a \u0431\u0435\u0437 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b/\u0431\u0435\u0437 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u043f\u043e \u043a\u0430\u0436\u0434\u043e\u043c\u0443 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0443; \u0442\u0430\u0431\u043b\u0438\u0446\u0430 Missing.\n- **\u0420\u0430\u0437\u0431\u0438\u0432\u043a\u0438:** \u043f\u043e \u0444\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e\u043c\u0443 \u0437\u0430\u0440\u044f\u0434\u0443, \u0447\u0438\u0441\u043b\u0443 \u043a\u043e\u043b\u0435\u0446, \u0430\u0440\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u0438 (0/1+), \u0447\u0438\u0441\u043b\u0443 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 \u2014 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0438 \u0438 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u0432\u043d\u0443\u0442\u0440\u0438 \u0433\u0440\u0443\u043f\u043f.\n- **\u041e\u0442\u0447\u0451\u0442:** \u0441\u0432\u043e\u0434\u043d\u0430\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0438 + \u0440\u0430\u0437\u0434\u0435\u043b \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0430 (parse-rate, coverage, \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u0441\u0432\u0435\u0440\u0445 \u0434\u043e\u043f\u0443\u0441\u043a\u043e\u0432) + \u043a\u0440\u0430\u0442\u043a\u0430\u044f \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u044f.\n\n## 6. \u0420\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u043c\u043e\u0441\u0442\u044c \u0438 \u0444\u043e\u043b\u0431\u044d\u043a\n- **\u0426\u0435\u043b\u0435\u0432\u043e\u0439 \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0439 (RDKit \u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d):** \u043f\u043b\u0430\u043d \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c; \u0432\u0441\u0435 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430 \u2014 2D, \u0434\u0435\u0448\u0451\u0432\u044b\u0435; \u043d\u0430 224 CPU \u043f\u0440\u0438 \u0431\u043e\u043b\u044c\u0448\u043e\u043c \u0440\u0430\u0437\u043c\u0435\u0440\u0435 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u0440\u0430\u0441\u043f\u0430\u0440\u0430\u043b\u043b\u0435\u043b\u0438\u0442\u044c \u0440\u0430\u0441\u0447\u0451\u0442 \u043f\u043e \u0447\u0430\u043d\u043a\u0430\u043c; \u0434\u043b\u044f \u0442\u0438\u043f\u043e\u0432\u044b\u0445 \u0440\u0430\u0437\u043c\u0435\u0440\u043e\u0432 \u043e\u0434\u043d\u043e\u043f\u043e\u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u0430. \u0423\u0441\u043b\u043e\u0432\u0438\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u043e\u0441\u0442\u0438 \u2014 \u043f\u0440\u0435\u0434\u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044b\u0439 RDKit + numpy/pandas \u0438 \u0438\u0445 \u0432\u0435\u0440\u0441\u0438\u0438; \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u0441\u0435\u0442\u0438 \u043d\u0435 \u043c\u0435\u0448\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u043f\u0430\u043a\u0435\u0442\u044b \u0443\u0436\u0435 \u0435\u0441\u0442\u044c.\n- **\u0422\u0435\u043a\u0443\u0449\u0435\u0435 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0435 \u044d\u0442\u043e\u043c\u0443 \u0443\u0441\u043b\u043e\u0432\u0438\u044e \u041d\u0415 \u0443\u0434\u043e\u0432\u043b\u0435\u0442\u0432\u043e\u0440\u044f\u0435\u0442** (\u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043e: rdkit/numpy/pandas/scipy \u043d\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u044b, \u0441\u0435\u0442\u0438 \u043d\u0435\u0442) \u2192 \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u043e\u0441\u0442\u044c \u0432 \u044d\u0442\u043e\u0439 \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u0435 = \u043f\u0440\u0435\u0434\u043c\u0435\u0442 \u0440\u0430\u0437\u0432\u0451\u0440\u0442\u044b\u0432\u0430\u043d\u0438\u044f \u0441\u0440\u0435\u0434\u044b, \u0430 \u043d\u0435 \u0434\u0438\u0437\u0430\u0439\u043d\u0430. \u0424\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435, \u0430 \u043d\u0435 \u043a\u0430\u043a \u00ab\u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043f\u0440\u043e\u0448\u0451\u043b\u00bb.\n- **\u0424\u043e\u043b\u0431\u044d\u043a \u0431\u0435\u0437 RDKit (\u0441\u043c\u043e\u0443\u043a-\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, \u043d\u0435 \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442):** \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0440\u0443\u0447\u043d\u043e\u0439 \u043f\u0430\u0440\u0441\u0435\u0440 SMILES/SDF \u0434\u0430\u0451\u0442 \u0430\u0442\u043e\u043c\u043d\u044b\u0435 \u0441\u0447\u0451\u0442\u0447\u0438\u043a\u0438, \u0447\u0438\u0441\u043b\u043e \u0441\u0432\u044f\u0437\u0435\u0439, \u0444\u043e\u0440\u043c\u0443\u043b\u0443, MW \u0438 \u0442\u043e\u0447\u043d\u0443\u044e \u043c\u0430\u0441\u0441\u0443 (\u043f\u043e \u0442\u0430\u0431\u043b\u0438\u0446\u0435 \u0430\u0442\u043e\u043c\u043d\u044b\u0445 \u043c\u0430\u0441\u0441), \u0444\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0437\u0430\u0440\u044f\u0434 (\u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u043d\u043e). **\u0422\u0435\u0440\u044f\u044e\u0442\u0441\u044f/\u0441\u0438\u043b\u044c\u043d\u043e \u0434\u0435\u0433\u0440\u0430\u0434\u0438\u0440\u0443\u044e\u0442:** TPSA (\u043d\u0435\u0442), logP-Crippen (\u043d\u0435\u0442), \u043a\u043e\u043b\u044c\u0446\u0430/SSSR (\u043d\u0435\u0442 \u0434\u043b\u044f \u0430\u0440\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0444\u043e\u0440\u043c, \u0447\u0430\u0441\u0442\u0438\u0447\u043d\u043e \u0434\u043b\u044f \u044f\u0432\u043d\u044b\u0445), \u0442\u043e\u0447\u043d\u044b\u0435 HBD/HBA (\u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438\u0431\u043b\u0438\u0436\u0451\u043d\u043d\u043e \u043f\u043e \u0442\u0438\u043f\u0430\u043c O/N), \u0441\u0442\u0435\u0440\u0435\u043e-\u0430\u043d\u0430\u043b\u0438\u0437. \u0420\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0430\u0446\u0438\u044f: \u0444\u043e\u043b\u0431\u044d\u043a \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f smoke-\u0442\u0435\u0441\u0442\u0430 \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d\u0430 \u043d\u0430 \u0440\u0435\u043f\u0435\u0440\u043d\u044b\u0445 SMILES, \u043d\u0435 \u0434\u043b\u044f \u0438\u0442\u043e\u0433\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b.\n- **\u0420\u0438\u0441\u043a\u0438:** \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 RDKit; \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 \u0434\u043b\u044f \u0438\u043d\u0442\u0435\u0433\u0440\u0430\u0446\u0438\u043e\u043d\u043d\u043e\u0433\u043e \u0442\u0435\u0441\u0442\u0430 \u2192 \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f \u043d\u0430 \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0441\u0442\u0440\u043e\u043a\u0430\u0445 \u0438 \u0440\u0435\u043f\u0435\u0440\u043d\u043e\u043c \u043d\u0430\u0431\u043e\u0440\u0435; \u043c\u0435\u0436\u0432\u0435\u0440\u0441\u0438\u043e\u043d\u043d\u044b\u0435 \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u044f \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0439 logP/HBA/TPSA; \u043f\u043e\u0442\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u043e \u0431\u043e\u043b\u044c\u0448\u043e\u0439 \u0440\u0430\u0437\u043c\u0435\u0440 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430.\n\n## 7. \u0424\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0434\u0438\u0437\u0430\u0439\u043d-\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0438 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e (\u0432\u044b\u0431\u0440\u0430\u043d\u044b \u044f\u0432\u043d\u043e, \u043d\u0435 \u0432\u044b\u0434\u0430\u044e\u0442\u0441\u044f \u0437\u0430 \u0444\u0430\u043a\u0442\u044b \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430)\n1. **\u0421\u043e\u043b\u0438/\u043a\u043e\u043d\u0442\u0440-\u0438\u043e\u043d\u044b:** \u0434\u0435\u0441\u0430\u043b\u0442\u0438\u043d\u0433 \u2014 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u043c \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u043e\u0440\u0433\u0430\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0447\u0435\u0440\u0435\u0437 \u0440\u0430\u0437\u0440\u044b\u0432 \u0441\u0432\u044f\u0437\u0435\u0439 \u043a \u0438\u043e\u043d\u0430\u043c); \u0438\u0441\u0445\u043e\u0434\u043d\u044b\u0439 SMILES \u0445\u0440\u0430\u043d\u0438\u0442\u0441\u044f \u0432 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0439 \u043a\u043e\u043b\u043e\u043d\u043a\u0435 \u0434\u043b\u044f \u0442\u0440\u0430\u0441\u0441\u044b.\n2. **\u0417\u0430\u0440\u044f\u0434\u044b:** \u0444\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u0435 \u0437\u0430\u0440\u044f\u0434\u044b \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u043c \u043a\u0430\u043a \u0432 \u0438\u0441\u0445\u043e\u0434\u043d\u0438\u043a\u0435; HBA/HBD \u2014 \u043f\u043e \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u043c \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f\u043c RDKit.\n3. **\u0414\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u044b/\u0441\u0442\u0435\u0440\u0435\u043e:** \u0434\u0435\u0434\u0443\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u044f \u043f\u043e InChIKey \u0441 \u0444\u043b\u0430\u0433\u043e\u043c \u00ab\u0434\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u00bb; \u0441\u0442\u0435\u0440\u0435\u043e-\u0440\u0430\u0437\u043b\u0438\u0447\u043d\u044b\u0435 \u0438\u0437\u043e\u043c\u0435\u0440\u044b \u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f \u0440\u0430\u0437\u043d\u044b\u043c\u0438 \u0441\u043e\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u044f\u043c\u0438.\n4. **logP:** \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c \u0440\u0435\u0434\u0430\u043a\u0446\u0438\u044e **Crippen** (`Crippen.MolLogP`), \u043d\u0435 \u043a\u043e\u043d\u0441\u0435\u043d\u0441\u0443\u0441\u043d\u0443\u044e; \u0440\u0435\u0434\u0430\u043a\u0446\u0438\u044f \u0443\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432 \u043e\u0442\u0447\u0451\u0442\u0435.\n5. **\u0412\u0435\u0440\u0441\u0438\u044f RDKit:** \u043e\u0434\u043d\u0430 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f (\u0446\u0435\u043b\u0435\u0432\u0430\u044f 2023.09.x), \u0437\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432 \u043e\u0442\u0447\u0451\u0442; \u0434\u043e\u043f\u0443\u0441\u043a\u0438 \u043f\u0435\u0440\u0435\u0441\u0447\u0451\u0442\u0430 \u043e\u0441\u043c\u044b\u0441\u043b\u0435\u043d\u043d\u044b \u0442\u043e\u043b\u044c\u043a\u043e \u0432\u043d\u0443\u0442\u0440\u0438 \u044d\u0442\u043e\u0439 \u0432\u0435\u0440\u0441\u0438\u0438.\n6. **\u041f\u0440\u043e\u043f\u0443\u0441\u043a\u0438:** \u043f\u0443\u0441\u0442\u044b\u0435/\u043d\u0435\u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0435 SMILES \u2192 missing, \u043d\u0435 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u044e\u0442 \u0432 \u0440\u0430\u0441\u0447\u0451\u0442\u0435 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432, \u0432\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u0441\u044f \u0432 coverage.\n\n## 8. \u0427\u0442\u043e \u041d\u0415 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442\u0441\u044f\n- \u042d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043d\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u043b\u0441\u044f; \u0447\u0438\u0441\u043b\u043e\u0432\u044b\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u043d\u0435 \u043f\u0440\u0438\u0432\u043e\u0434\u044f\u0442\u0441\u044f (\u043a\u0440\u043e\u043c\u0435 \u0440\u0443\u0447\u043d\u044b\u0445 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0439 \u0440\u0435\u043f\u0435\u0440\u043d\u043e\u0433\u043e \u043d\u0430\u0431\u043e\u0440\u0430 \u043a\u0430\u043a \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u044b\u0445 \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u043e\u0432); \u0432\u044b\u0432\u043e\u0434\u0438\u043c\u044b\u0435 \u0437\u0430\u043a\u043e\u043d\u043e\u043c\u0435\u0440\u043d\u043e\u0441\u0442\u0438 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u043a\u043e\u043b\u043b\u0438\u043d\u0435\u0430\u0440\u043d\u043e\u0441\u0442\u044c MW\u2194\u0447\u0438\u0441\u043b\u043e \u0430\u0442\u043e\u043c\u043e\u0432 \u0432 \u043a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u043e\u043d\u043d\u043e\u0439 \u043c\u0430\u0442\u0440\u0438\u0446\u0435) \u043e\u0431\u043e\u0437\u043d\u0430\u0447\u0435\u043d\u044b \u043a\u0430\u043a \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u044f/\u043f\u043b\u0430\u043d \u043d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u044f, \u0430 \u043d\u0435 \u043a\u0430\u043a \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435.", "evidence": "\u0420\u0430\u0437\u0432\u0435\u0434\u043a\u0430 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044f (\u043d\u0435 \u0437\u0430\u043f\u0443\u0441\u043a \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430): `/workspace` \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e task.json; \u0444\u0430\u0439\u043b\u043e\u0432 *.smi/*.sdf/*.csv/*.parquet \u043d\u0430 \u0434\u0438\u0441\u043a\u0435 \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u043e; Python 3.14.4; `import rdkit/numpy/pandas/scipy` \u2192 ModuleNotFoundError; pip-\u043a\u044d\u0448 `~/.cache/pip` \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442; \u0441\u0440\u0435\u0434\u0430 bubblewrap, network disabled. \u0421\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u